"""Flask backend para Vercel - Sueldos App"""

from flask import Flask, jsonify, request
from flask_cors import CORS
import sqlite3
import base64
import os

app = Flask(__name__)
CORS(app)

_DB_B64 = "_db_path():"

def get_db_path():
    """Descodifica BD desde base64"""
    db_path = '/tmp/sueldos.db'
    if not os.path.exists(db_path):
        db_bytes = base64.b64decode(_DB_B64)
        with open(db_path, 'wb') as f:
            f.write(db_bytes)
    return db_path

def get_connection():
    """Abre conexión a SQLite"""
    db_path = get_db_path()
    conn = sqlite3.connect(db_path, timeout=10.0)
    conn.row_factory = sqlite3.Row
    return conn

@app.route('/api/health', methods=['GET'])
def health():
    try:
        conn = get_connection()
        cursor = conn.cursor()
        cursor.execute("SELECT COUNT(*) FROM empleados")
        count = cursor.fetchone()[0]
        conn.close()
        return jsonify({'status': 'ok', 'empleados': count}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/empleados', methods=['GET'])
def get_empleados():
    try:
        conn = get_connection()
        cursor = conn.cursor()
        cursor.execute("""
            SELECT e.*, c.nombre as categoria_nombre, c.precio_dia
            FROM empleados e
            LEFT JOIN categorias c ON e.categoria_id = c.id
            ORDER BY e.apellido, e.nombre
        """)
        rows = cursor.fetchall()
        conn.close()
        return jsonify([dict(row) for row in rows]), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/quincenas', methods=['GET'])
def get_quincenas():
    try:
        conn = get_connection()
        cursor = conn.cursor()
        cursor.execute("SELECT * FROM quincenas ORDER BY id DESC")
        rows = cursor.fetchall()
        conn.close()
        return jsonify([dict(row) for row in rows]), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/quincenas/<int:quincena_id>', methods=['GET'])
def get_quincena_detail(quincena_id):
    """Get quincena with liquidaciones"""
    try:
        conn = get_connection()
        cursor = conn.cursor()
        
        cursor.execute("SELECT * FROM quincenas WHERE id = ?", (quincena_id,))
        quincena = cursor.fetchone()
        if not quincena:
            return jsonify({'error': 'Quincena not found'}), 404
        
        cursor.execute("""
            SELECT l.*, e.nombre, e.apellido, e.legajo, c.nombre as categoria
            FROM liquidaciones l
            JOIN empleados e ON l.empleado_id = e.id
            JOIN categorias c ON e.categoria_id = c.id
            WHERE l.quincena_id = ?
            ORDER BY e.apellido, e.nombre
        """, (quincena_id,))
        liquidaciones = [dict(row) for row in cursor.fetchall()]
        
        conn.close()
        return jsonify({
            'quincena': dict(quincena),
            'liquidaciones': liquidaciones
        }), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

